entity Prob_6_52_vhdl is	port (A_par: buffer bit_vector (3 downto 0); In_par: in bit_vector (3 downto 0); MSB_in, LSB_in, s1, s0, CLK, Clear_b: in bit);end Prob_6_52_vhdl;architecture Structural of Prob_6_52_vhdl is	signal y0, y1, y2, y3: bit;	component Mux_4x1 port (y: out bit; in3, in2, in1, in0, s1, s0: in bit); end component;	component D_FF port (q: out bit; d, clk, clr_b: in bit); end component;beginM0:  Mux_4x1 port map (y0, In_par(0),  LSB_in, A_par(1), A_par(0), s1, s0);M1:  Mux_4x1 port map (y1, In_par(1), A_par(0), A_par(2), A_par(1), s1, s0);M2: Mux_4x1 port map (y2, In_par(2), A_par(1), A_par(3), A_par(2), s1, s0);M3: Mux_4x1 port map (y3, In_par(3), A_par(2), MSB_in, A_par(3), s1, s0);D0:  D_FF port map (A_par(0), y0, CLK, Clear_b);D1:  D_FF port map (A_par(1), y1, CLK, Clear_b);D2:  D_FF port map (A_par(2), y2, CLK, Clear_b);D3:  D_FF port map (A_par(3), y3, CLK, Clear_b);end Structural;entity Mux_4x1 is	port (y: out bit; in3, in2, in1, in0, s1, s0: in bit);end Mux_4x1;architecture Behavioral of Mux_4x1 isbegin	process  (in3, in2, in1, in0, s1, s0) begin		case (s1 &  s0) is      	when "00" =>	y <= in0;      	when "01" =>	y <= in1;			when "10" =>	y <= in2;			when "11" =>	y <= in3;		end case;	end process;end Behavioral;entity D_FF is	port (q: out bit; d, clk, clr_b: in bit);end D_FF;architecture Behavioral of D_FF isbegin  process   (clk, clr_b) begin    if (clr_b = '0') then q <= '0'; else q <= d; end if;  end process;end Behavioral;